head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/**
 * @method
 * @name getCookie
 * @description desc
 * @param {string} Name desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getCookie = function(Name) {
    var search = Name + "=";
    if (document.cookie.length > 0) {
        // 쿠키가 설정되어 있다면
        offset = document.cookie.indexOf(search);
        if (offset != -1) {
            // 쿠키가 존재하면
            offset += search.length; // set index of beginning of value
            end = document.cookie.indexOf(";", offset); // 쿠키 값의 마지막 위치 인덱스 번호 설정
            if (end == -1) end = document.cookie.length;
            return unescape(document.cookie.substring(offset, end));
        }
    }
    return "";
};


/*
 * 상장업무처리 메세지 처리
 */
LastJob = "";
/**
 * @method
 * @name fn_isProcess
 * @description desc
 * @param {string} gubun desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_isProcess = function(gubun) {
    if (gubun == 'I') scwin.LastJob = '저장';

    else if (gubun == 'U') scwin.LastJob = '수정';

    else if (gubun == 'D') scwin.LastJob = '삭제';

    else if (gubun == 'S') scwin.LastJob = '제출';
    if (!window.confirm("[" + scwin.LastJob + "] 하시겠습니까?")) {
        return false;
    }
    return true;
};


/* ETN신청 다중제출 */
/**
 * @method
 * @name fn_EtnSelectSub
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_EtnSelectSub = function() {
    if (!$("[name='checkSub']").is(':checked')) {
        alert('선택된 항목이 없습니다.');
        return;
    }
    if (!scwin.fn_isProcess('S')) return;
    form = document.etnListForm;
    form.action = '/etn/EtnList.do';
    form.method.setValue('submitMultiList');
    form.submit();
};


/* ETN 엑셀 템플릿 다운로드*/
/**
 * @method
 * @name fn_EtnExcelDownload
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_EtnExcelDownload = function() {
    form = document.etnListForm;
    form.action = '/etn/EtnList.do';
    form.method.setValue('etnExcelDownload');
    form.submit();
};


