*/
/**
 * @method
 * @name fn_EtnExcelUploadPop
 * @description desc
 * @param {string} listBzCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_EtnExcelUploadPop = function(listBzCd) {
    var i = 0;
    i++;
    var popName = "pop_excelUpload_" + i;
    var urlLink = "";
    if (scwin.getCookie(popName) != popName) {
        if (listBzCd == 0) {
            urlLink = "/etn/JLDFIL70211.jsp";
        } else if (listBzCd == 1) {
            urlLink = "/etn/JLDFIL70311.jsp";
        } else if (listBzCd == 2) {
            urlLink = "/etn/JLDFIL70411.jsp";
        } else if (listBzCd == 3) {
            urlLink = "/etn/JLDFIL70511.jsp";
        }
        window.open(urlLink, popName, "scrollbars=no,toolbar=no,resizable=yes,width=500,height=500,left=0,top=0");
    }
};



/* 선택제출 체크박스 전체선택/전체해제*/
$(document).ready(function() {
    $("#checkAll").click(function() {
        if ($(this).is(":checked")) {
            $("input:checkbox[name='checkSub']").attr("checked", true);
        } else {
            $("input:checkbox[name='checkSub']").attr("checked", false);
        }
    });
});
